package ing.fuyaoskyrocket.photoinfo.domain.media

import java.io.ByteArrayOutputStream
import java.nio.ByteBuffer
import java.util.UUID

/**
 * Apple Photographic Styles payload, ported from the device-verified layout of
 * BeetMan/XDRemux-Flutter (Apache-2.0): an identity Standard style injected into HEIF.
 */
internal object AppleStyleMetadata {
    const val STYLES_CONTENT_TYPE = "tag:apple.com,2023:photo:metadata:styles"
    const val DELTA_MAP_URN = "tag:apple.com,2023:photo:aux:styledeltamap"
    const val LINEAR_THUMBNAIL_URN = "tag:apple.com,2023:photo:aux:linearthumbnail"
    const val SKY_MATTE_URN = "urn:com:apple:photo:2020:aux:semanticskymatte"
    const val SKY_MATTE_VERSION = 65536
    private const val STYLE_BLOCKS = 864

    /** Runtime flag bplist carried in Apple MakerNote tag 84, golden sample bytes. */
    val TAG_84 = byteArrayOf(
        0x62, 0x70, 0x6c, 0x69, 0x73, 0x74, 0x30, 0x30, 0xd8.toByte(), 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
        0x08, 0x09, 0x0a, 0x0a, 0x0a, 0x0a, 0x09, 0x0b, 0x09, 0x51, 0x37, 0x51, 0x33, 0x51, 0x34, 0x51,
        0x30, 0x51, 0x35, 0x51, 0x31, 0x51, 0x36, 0x51, 0x32, 0x10, 0x00, 0x10, 0x01, 0x10, 0x04, 0x08,
        0x19, 0x1b, 0x1d, 0x1f, 0x21, 0x23, 0x25, 0x27, 0x29, 0x2b, 0x2d, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x01, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0c, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2f,
    )

    val skyMatteXmp: String = """
        <x:xmpmeta xmlns:x="adobe:ns:meta/" x:xmptk="XMP Core 6.0.0">
           <rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">
              <rdf:Description rdf:about=""
                    xmlns:semanticSegmentationMatte="http://ns.apple.com/semanticSegmentationMatte/1.0/">
                 <semanticSegmentationMatte:SemanticSegmentationMatteVersion>$SKY_MATTE_VERSION</semanticSegmentationMatte:SemanticSegmentationMatteVersion>
              </rdf:Description>
           </rdf:RDF>
        </x:xmpmeta>
    """.trimIndent() + "\n"

    /** Identity lattice: 864 blocks of 30 little-endian f16 values, 1.0 at [3, 7, 11]. */
    fun identityStyleData(): ByteArray {
        val out = ByteArray(STYLE_BLOCKS * 30 * 2)
        var at = 0
        repeat(STYLE_BLOCKS) {
            for (index in 0 until 30) {
                val value = if (index == 3 || index == 7 || index == 11) 0x3c00 else 0
                out[at++] = value.toByte()
                out[at++] = (value shr 8).toByte()
            }
        }
        return out
    }

    fun newIdentifier(): String = UUID.randomUUID().toString().uppercase(java.util.Locale.ROOT)

    /** The styleMetadata binary plist describing an identity (Standard) photographic style. */
    fun styleMetadata(): ByteArray {
        val writer = BplistWriter()
        val top = writer.run {
            val k0 = addStr("0"); val v0 = addInt(15)
            val kf = addStr("f"); val vf = addInt(32)
            val k1 = addStr("1"); val v1 = addData(identityStyleData())
            val kj = addStr("j"); val vj = addReal(1.0)
            val kg = addStr("g"); val vg = addInt(1278226536)
            val k4 = addStr("4"); val v4 = addReal(4.0)
            val ki = addStr("i")
            val vi = run {
                val a = addStr("OriginalRangeMin"); val av = addReal(0.0)
                val b = addStr("OriginalRangeMax"); val bv = addReal(0.0762939453125)
                val c = addStr("Gain"); val cv = addReal(7.353515625)
                addDict(listOf(a to av, b to bv, c to cv))
            }
            val k6 = addStr("6"); val v6 = addStats(writer)
            val kc = addStr("c"); val vc = addData(FIELD_C)
            val kk = addStr("k"); val vk = addBool(false)
            val kh = addStr("h"); val vh = addReal(1.8384023904800415)
            val k2 = addStr("2"); val v2 = addBool(true)
            val k5 = addStr("5"); val v5 = addInt(2)
            val k3 = addStr("3"); val v3 = addData(FIELD_3)
            val ke = addStr("e"); val ve = addInt(32)
            val k7 = addStr("7")
            val v7 = run {
                val a = addStr("PersonMasksValidHint"); val av = addReal(-1.0)
                val b = addStr("SkinRatio"); val bv = addReal(0.0)
                val c = addStr("PeopleRatio"); val cv = addReal(0.0)
                addDict(listOf(a to av, b to bv, c to cv))
            }
            val kd = addStr("d"); val vd = addData(FIELD_D)
            addDict(listOf(k0 to v0, kf to vf, k1 to v1, kj to vj, kg to vg, k4 to v4, ki to vi, k6 to v6,
                kc to vc, kk to vk, kh to vh, k2 to v2, k5 to v5, k3 to v3, ke to ve, k7 to v7, kd to vd))
        }
        return writer.finish(top)
    }

    private fun addStats(writer: BplistWriter): Int = writer.run {
        fun zero(): Int {
            val keys = listOf("highKey", "p75", "p25", "blackPoint", "p02", "p50", "whitePoint", "p10", "p98")
                .map { addStr(it) to addReal(if (it == "highKey") 1.0 else 0.0) }
            return addDict(keys)
        }
        fun toneMapped(): Int {
            val values = listOf("p02" to 0.0055912993848323805, "p98" to 1.0064338445663452,
                "p10" to 0.016773898154497147, "blackPoint" to 0.0, "p75" to 0.24042586982250214,
                "highKey" to 0.5505164861679077, "whitePoint" to 0.0, "p50" to 0.08946079015731809,
                "p25" to 0.0279564969241619)
            return addDict(values.map { addStr(it.first) to addReal(it.second) })
        }
        fun linear(): Int {
            val values = listOf("blackPoint" to 0.0, "whitePoint" to 0.0, "p02" to 0.00032384536461904645,
                "p50" to 0.0032384535297751427, "highKey" to 0.9925689101216177, "p98" to 0.04630988836288451,
                "p75" to 0.009391515515744686, "p25" to 0.0009715360938571393, "p10" to 0.0006476907292380929)
            return addDict(values.map { addStr(it.first) to addReal(it.second) })
        }
        val entries = listOf(
            "LinearImagePersonSegmentBased" to zero(),
            "ToneMappedImageRedChannelSkinBased" to zero(),
            "ToneMappedImagePersonSegmentBased" to zero(),
            "LinearGTCImage" to zero(),
            "ToneMappedImage" to toneMapped(),
            "ToneMappedImageGreenChannelSkinBased" to zero(),
            "LinearImage" to linear(),
            "LinearImageSkinBased" to zero(),
            "ToneMappedImageBlueChannelSkinBased" to zero(),
            "ToneMappedImageSkinBased" to zero(),
        )
        return addDict(entries.map { addStr(it.first) to it.second })
    }

    /**
     * Apple MakerNote assembled from the independent capabilities: the live-photo pairing
     * identifier (tag 17), the portrait marker (tag 20), and the style photo identifier
     * (tag 43) with the runtime flag plist (tag 84).
     */
    fun appleNote(liveIdentifier: String?, portrait: Boolean, styleIdentifier: String?): ByteArray {
        require(liveIdentifier != null || portrait || styleIdentifier != null)
        data class Entry(val tag: Int, val type: Int, val count: Int, val payload: ByteArray?, val inline: Int = 0)
        val entries=mutableListOf<Entry>()
        liveIdentifier?.let {
            require(it.length == 36)
            entries+=Entry(17, 2, 37, it.uppercase(java.util.Locale.ROOT).toByteArray(Charsets.US_ASCII)+byteArrayOf(0))
        }
        if(portrait) entries+=Entry(20, 9, 1, null, 2)
        styleIdentifier?.let {
            require(it.length == 36)
            entries+=Entry(43, 2, 37, it.uppercase(java.util.Locale.ROOT).toByteArray(Charsets.US_ASCII)+byteArrayOf(0))
            entries+=Entry(84, 7, 91, TAG_84)
        }
        entries.sortBy { it.tag }
        val base=16+entries.size*12+4
        var at=base
        val out=ByteArrayOutputStream()
        out.write("Apple iOS\u0000\u0000\u0001".toByteArray(Charsets.US_ASCII))
        out.write(byteArrayOf('M'.code.toByte(), 'M'.code.toByte()))
        out.write(byteArrayOf((entries.size shr 8).toByte(), entries.size.toByte()))
        entries.forEach { entry ->
            val offset=if(entry.payload!=null) at else 0
            out.write(ByteBuffer.allocate(12).putShort(entry.tag.toShort()).putShort(entry.type.toShort())
                .putInt(entry.count).putInt(if(entry.payload!=null) offset else entry.inline).array())
            if(entry.payload!=null) at+=entry.payload.size
        }
        out.write(byteArrayOf(0, 0, 0, 0))
        entries.forEach { entry -> entry.payload?.let(out::write) }
        return out.toByteArray()
    }

    fun stylesNote(identifier: String, includePortrait: Boolean): ByteArray =
        appleNote(null, includePortrait, identifier)

