    private class BplistWriter {
        private sealed interface Object
        private data class Bool(val value: Boolean) : Object
        private data class IntValue(val value: Long) : Object
        private data class RealValue(val value: Double) : Object
        private data class DataValue(val value: ByteArray) : Object
        private data class StrValue(val value: String) : Object
        private data class DictValue(val entries: List<Pair<Int, Int>>) : Object

        private val objects = mutableListOf<Object>()

        fun addBool(value: Boolean): Int { objects += Bool(value); return objects.size - 1 }
        fun addInt(value: Long): Int { objects += IntValue(value); return objects.size - 1 }
        fun addReal(value: Double): Int { objects += RealValue(value); return objects.size - 1 }
        fun addData(value: ByteArray): Int { objects += DataValue(value); return objects.size - 1 }
        fun addStr(value: String): Int { objects += StrValue(value); return objects.size - 1 }
        fun addDict(entries: List<Pair<Int, Int>>): Int { objects += DictValue(entries); return objects.size - 1 }

        fun finish(top: Int): ByteArray {
            val out = ByteArrayOutputStream()
            out.write("bplist00".toByteArray(Charsets.US_ASCII))
            val offsets = IntArray(objects.size)
            objects.forEachIndexed { index, obj ->
                offsets[index] = out.size()
                writeObject(out, obj)
            }
            val refSize = if (objects.size <= 255) 1 else 2
            val offsetTableAt = out.size()
            val offsetSize = when {
                offsetTableAt + 8 <= 0xff -> 1
                offsetTableAt + 8 <= 0xffff -> 2
                else -> 4
            }
            offsets.forEach { offset ->
                when (offsetSize) {
                    1 -> out.write(offset)
                    2 -> out.write(byteArrayOf((offset shr 8).toByte(), offset.toByte()))
                    else -> out.write(ByteBuffer.allocate(4).putInt(offset).array())
                }
            }
            val trailer = ByteBuffer.allocate(32)
            trailer.put(6, offsetSize.toByte())
            trailer.put(7, refSize.toByte())
            trailer.putLong(8, objects.size.toLong())
            trailer.putLong(16, top.toLong())
            trailer.putLong(24, offsetTableAt.toLong())
            out.write(trailer.array())
            return out.toByteArray()
        }

        private fun writeObject(out: ByteArrayOutputStream, obj: Object) {
            fun lengthPrefix(marker: Int, length: Int) {
                if (length < 15) out.write(marker or length)
                else {
                    out.write(marker or 0x0f)
                    when {
                        length <= 0xff -> { out.write(0x10); out.write(length) }
                        length <= 0xffff -> { out.write(0x11); out.write(byteArrayOf((length shr 8).toByte(), length.toByte())) }
                        else -> { out.write(0x12); out.write(ByteBuffer.allocate(4).putInt(length).array()) }
                    }
                }
            }
            when (obj) {
                is Bool -> out.write(if (obj.value) 0x09 else 0x08)
                is IntValue -> {
                    val bytes = when {
                        obj.value.toInt().toLong() == obj.value && obj.value in 0..0xff -> 1
                        obj.value in 0..0xffff -> 2
                        obj.value in 0..0xffffffffL -> 4
                        else -> 8
                    }
                    out.write(0x10 or (Integer.numberOfTrailingZeros(bytes)))
                    val buffer = ByteBuffer.allocate(8).putLong(obj.value).array()
                    out.write(buffer.copyOfRange(8 - bytes, 8))
                }
                is RealValue -> {
                    out.write(0x23)
                    out.write(ByteBuffer.allocate(8).putDouble(obj.value).array())
                }
                is DataValue -> {
                    lengthPrefix(0x40, obj.value.size)
                    out.write(obj.value)
                }
                is StrValue -> {
                    val bytes = obj.value.toByteArray(Charsets.US_ASCII)
                    lengthPrefix(0x50, bytes.size)
                    out.write(bytes)
                }
                is DictValue -> {
                    lengthPrefix(0xd0, obj.entries.size)
                    fun ref(value: Int) {
                        val size = if (objects.size <= 255) 1 else 2
                        if (size == 1) out.write(value) else out.write(byteArrayOf((value shr 8).toByte(), value.toByte()))
                    }
                    obj.entries.forEach { ref(it.first) }
                    obj.entries.forEach { ref(it.second) }
                }
            }
        }
    }
}
